int parseEstimate(const QString &text)
{
    int total = 0;
    const QStringList parts = text.split(' ', Qt::SkipEmptyParts);
    if (parts.isEmpty())
        return -1;
    for (const QString &part : parts) {
        if (part.isEmpty())
            return -1;
        QChar unit = part.back();
        QString numPart = part.left(part.size() - 1);
        int value = 0;
        bool ok = false;
        if (numPart.isEmpty())
            return -1;
        value = numPart.toInt(&ok);
        if (!ok)
            return -1;
        if (value < 0)
            return -1;
        if (unit == 'w')
            total += value * 5 * 8 * 60;  // 2400
        else if (unit == 'd')
            total += value * 8 * 60;      // 480
        else if (unit == 'h')
            total += value * 60;
        else if (unit == 'm')
            total += value;
        else
            return -1;
    }
    return total;
}
```

